 const query=tx.select().from(s.overtimePatternVersion).where(and(eq(s.overtimePatternVersion.tenantId,ctx.tenantId),eq(s.overtimePatternVersion.id,uuid(id)))).limit(1);const [row]=await(lock?query.for('update'):query);if(!row)fail('unavailable','The overtime version is unavailable.');return row;
