 const options=bounded(await tx.select().from(s.profileOption).where(and(eq(s.profileOption.tenantId,ctx.tenantId),eq(s.profileOption.isActive,true),inArray(s.profileOption.category,Object.values(PROFILE_FIELDS)))).orderBy(asc(s.profileOption.category),asc(s.profileOption.sortOrder),asc(s.profileOption.id)).limit(2001),2000);for(const [field,category]of Object.entries(PROFILE_FIELDS))choices[field as OvertimeField]=options.filter(row=>row.category===category).map(row=>({id:row.value,label:row.label}));
 return {companies,employees,employeeNextCursor:!p.employeeIds&&rows.length>limit?employees.at(-1)!.id:null,earningItems,choices,readerLimitations:['recordedPersonnelContext','financialScope']};
