async function validateActivationTx(tx:Tx,ctx:SessionContext,p:{versionId:string;expectedRevision:number}){
 const row=await versionRow(tx,ctx,p.versionId),pattern=await assertVersionAdmin(tx,ctx,row);if(row.revision!==p.expectedRevision||row.activatedAt||pattern.archivedAt)fail('stale','The draft changed or is no longer editable.');const companyIds=await companiesForVersion(tx,row.id),companies=await administerCompanies(tx,ctx,companyIds);const issues:OvertimeIssue[]=[];let requiredFields:OvertimeField[]=[],referenceDigest:string|null=null;
 try{const definition=validateOvertimePattern(row.definition);requiredFields=analyzeOvertimePattern(definition).requiredFields;issues.push(...analyzeOvertimePattern(definition).issues);if(definition.currency.minorScale!==currencyMinorScale(definition.currency.code)||companies.some(company=>company.currency!==definition.currency.code))fail('invalid','The pattern currency and canonical precision must match every selected company.');referenceDigest=await validateReferencesTx(tx,ctx,definition,companyIds);}catch(error){const issue=(error as {issue?:OvertimeIssue}).issue;issues.push(issue??{code:'invalid',path:'definition',severity:'error',detail:error instanceof Error?error.message:'Correct the overtime configuration.'});}
 const validationDigest=issues.some(issue=>issue.severity==='error')?null:digest({versionId:row.id,revision:row.revision,digest:row.digest,companyIds,companies,referenceDigest,definition:row.definition});return {validationDigest,issues,requiredFields};
}
export function validateOvertimePatternActivation(ctx:SessionContext,p:{versionId:string;expectedRevision:number}){return withAttendanceTenant(ctx,tx=>validateActivationTx(tx,ctx,p));}
export function activateOvertimePattern(ctx:SessionContext,p:{versionId:string;expectedRevision:number;validationDigest:string;effectiveFrom:string}){return withAttendanceTenant(ctx,async tx=>{await lockConfiguration(tx,ctx);date(p.effectiveFrom);if(p.effectiveFrom<todayInKualaLumpur())fail('invalid','Activation cannot backdate a new policy into historical attendance.');const row=await versionRow(tx,ctx,p.versionId,true),check=await validateActivationTx(tx,ctx,p);if(!check.validationDigest||p.validationDigest!==check.validationDigest)fail('stale','Validation or references changed. Validate again before activation.');await tx.update(s.overtimePatternVersion).set({activatedAt:new Date(),activatedBy:ctx.userId??null}).where(eq(s.overtimePatternVersion.id,row.id));await tx.insert(s.overtimePatternVersionState).values({tenantId:ctx.tenantId,versionId:row.id,sequence:1,state:'active',effectiveFrom:p.effectiveFrom,reason:'Validated activation',createdBy:ctx.userId??null});await event(tx,ctx,row.patternId,'version.activated',{versionId:row.id,digest:row.digest,effectiveFrom:p.effectiveFrom,validationDigest:check.validationDigest});return {versionId:row.id};});}
