 const peers=bounded(await tx.select().from(s.overtimePatternAssignment).where(and(eq(s.overtimePatternAssignment.tenantId,ctx.tenantId),eq(s.overtimePatternAssignment.priority,p.priority),isNull(s.overtimePatternAssignment.supersededAt),p.to?lt(s.overtimePatternAssignment.validFrom,p.to):undefined,or(isNull(s.overtimePatternAssignment.validTo),gt(s.overtimePatternAssignment.validTo,p.from)))).orderBy(asc(s.overtimePatternAssignment.id)).limit(501),500);
